// clone returns a concrete clone of the StockQuery for internal use by First/Only.
func (q *StockQuery) clone() *StockQuery {
	if q == nil {
		return nil
	}
	c := &StockQuery{
		config:        q.config,
		ctx:           q.ctx.Clone(),
		inters:        q.inters,
		modifiers:     runtime.CloneSlice(q.modifiers),
		order:         runtime.CloneSlice(q.order),
		path:          q.path,
		predicates:    runtime.CloneSlice(q.predicates),
		withFKs:       q.withFKs,
		withProduct:   q.withProduct.clone(),
		withWarehouse: q.withWarehouse.clone(),
	}
	return c
}

// loadWarehouse eagerly loads the "warehouse" edge for the given nodes.
func (q *StockQuery) loadWarehouse(ctx context.Context, query *WarehouseQuery, nodes []*entity.Stock, init func(*entity.Stock), assign func(*entity.Stock, *entity.Warehouse)) error {
	query = query.clone()
	fkSeen := make(map[int]struct{}, len(nodes))
	var fks []any
	for _, n := range nodes {
		if init != nil {
			init(n)
		}
		fkRaw := n.FKValue("warehouse_stocks")
		if fkRaw == nil {
			continue
		}
		fkVal := derefFK(fkRaw).(int)
		if _, ok := fkSeen[fkVal]; !ok {
			fkSeen[fkVal] = struct{}{}
			fks = append(fks, any(fkVal))
		}
	}
	if len(fks) == 0 {
		return nil
	}
	query.Where(func(s *sql.Selector) {
		s.Where(sql.In(s.C(warehouse.FieldID), fks...))
	})
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	neighborByID := make(map[int]*entity.Warehouse, len(neighbors))
	for _, n := range neighbors {
		neighborByID[n.ID] = n
	}
	for _, n := range nodes {
		fkRaw := n.FKValue("warehouse_stocks")
		if fkRaw == nil {
			continue
		}
		fkVal := derefFK(fkRaw).(int)
		if neighbor, ok := neighborByID[fkVal]; ok {
			assign(n, neighbor)
		}
	}
	return nil
}

